using RailwayWebBuilderCore.Enums;

namespace RailwayWebBuilderCore._SiteData.ModelRailways.Layouts;

internal class PlasterMill : LayoutBase
{
    public PlasterMill()
    {
        Name = LayoutNamesEnums.PlasterMill;
        Description = "Inspired by the water mill of J. C. Staton and its British Railways interchange at Tutbury, near Burton upon Trent, the layout is based on the exchange sidings and viaduct that once crossed the River Dove. The scale is 4mm:1ft, the track is laid to EM gauge standards and control is analogue, with the hand-built pointwork - all rescued from previous layouts - operated by slide switches that also set the polarity. The clock is loosely set at 1950 to 1960, a time when two Peckett saddle tanks shunted the mill and exchange sidings and traversed the viaduct to the main line sidings; motive power on the model is two BR-owned saddle tanks whose prototypes were based at Burton shed and recorded as stored there in 1951. Two main buildings feature - part of the prototype, built as a cotton mill in 1781, and the gatehouse with archway which serves as a scenic break - while the single-road engine shed can accommodate both locomotives. The mill closed in 1968, the buildings were demolished and the viaduct span removed in 1972; the site is now a play area, though a platform and some of the viaduct piers survive. Simplicity was the key word when building the layout and remains so during operation.";
    }
}
